""" Provide reasonable minor tick formatting for a log y axis.

    Provides ticks on the 2, 3, and 5 for every decade.

    Args:
        y: Tick value.
        pos: Tick position.
    Returns:
        Formatted label.
    """
def log_minor_tick_formatter(y: int, pos: float) -> str {
    ret_val = "";
    values_to_plot = [0, 1, 3];
    if ((pos % 8) in values_to_plot) {
        ret_val = f"{y:g}";
    }
    return ret_val;
}

""" Write a SAM tag in the format ``TAG:TYPE:data``
    >>> encode_tag('YM', 'Z', '#""9O"1@!J')
    'YM:Z:#""9O"1@!J'
    """
def encode_tag(tag: Any, data_type: Any, data: Any) -> object {
    value = ':'.join(`list((tag.upper(), data_type.upper(), data)));
    return value;
}

"""Counts number of satellites used in calculation from total visible satellites
    Arguments:
        feed feed=data_stream.satellites
    Returns:
        total_satellites(int):
        used_satellites (int):
    """
def satellites_used(feed: Any) -> object {
    total_satellites = 0;
    used_satellites = 0;
    if not isinstance(feed, `list) {
        return (0, 0);
    }
    for satellites in feed {
        total_satellites += 1;
        if (satellites['used'] is True) {
            used_satellites += 1;
        }
    }
    return (total_satellites, used_satellites);
}
